--             CREATE TABLE customer_code_formats (
--                                                    id INT PRIMARY KEY,
--                                                    format_customer_code VARCHAR(50),
--                                                    company VARCHAR(100),
--                                                    department VARCHAR(100),
--                                                    current_value DECIMAL(10, 2)
--             );
--

            DELETE FROM customer_code_formats;

            DELETE FROM customer;

            INSERT INTO
                customer_code_formats (
                id,
                format_customer_code,
                company,
                department,
                current_value
            )
            VALUES
                (2, 'ABC-%06d', 'string', 'Sales', 1),
                (3, 'XYZ-%06d', 'MASI', 'HR', 1),
                (4, 'MMS-%04d', 'MMS', NULL, 1),
                (1, 'KH-%04d', 'KIM_LONG', NULL, 1);


            ALTER TABLE customer ALTER COLUMN address DROP NOT NULL;
            ALTER TABLE customer ALTER COLUMN first_name DROP NOT NULL;
            ALTER TABLE customer ALTER COLUMN last_name DROP NOT NULL;
            ALTER TABLE customer ALTER COLUMN phone_number DROP NOT NULL;
            ALTER TABLE customer ALTER COLUMN email DROP NOT NULL;

